<template>
  <div class="space-y-5 fade-in">
    <header class="flex flex-wrap items-end justify-between gap-4"><div><div class="eyebrow">LOGICAL RELAY POOLS</div><h1 class="page-title">入口池</h1><p class="page-subtitle">一个逻辑节点绑定多台 CDT Relay；选择 DNS Provider 后只需填写记录名，完整入口域名会自动拼接。</p></div><button class="btn-primary" :disabled="!canCreate" @click="openCreate">创建入口池</button></header>
    <div v-if="!canCreate" class="notice notice-info">创建入口池前至少需要一台中转节点和一个落地节点。</div><div v-if="message" class="notice" :class="messageType==='error'?'notice-error':'notice-success'">{{ message }}</div>
    <section class="grid grid-cols-1 gap-4 xl:grid-cols-2 layout-collection layout-collection--row"><article v-for="pool in store.pools" :key="pool.id" class="card p-5 layout-card"><div class="pool-row-head flex items-start justify-between gap-3"><div class="min-w-0"><div class="flex items-center gap-2"><span class="pool-mark">POOL</span><h2 class="truncate font-bold text-slate-800">{{ pool.name }}</h2></div><p class="mt-2 truncate font-mono text-[11px] text-slate-400"><MaskedIP :value="pool.hostname" :suffix="`:${pool.listen_port}`" placeholder="未设置入口地址" /></p></div><div class="pool-badges"><span v-if="pool.front_door_mode==='dispatcher'" class="auto-drain-tag">固定 Dispatcher</span><span v-else-if="pool.auto_drain !== false" class="auto-drain-tag">自动排空</span><span class="state-tag" :class="pool.enabled?'state-online':''">{{ pool.enabled?'运行中':'已停用' }}</span></div></div><div class="pool-row-body mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4"><div class="info-box"><span>协议</span><strong>{{ pool.network.toUpperCase() }}</strong></div><div class="info-box"><span>在线 Relay</span><strong>{{ onlineMembers(pool) }}/{{ activeMembers(pool) }}</strong></div><div class="info-box"><span>落地目标</span><strong>{{ pool.targets.length }}</strong></div><div class="info-box"><span>入口</span><strong>{{ pool.front_door_mode==='dispatcher' ? '固定前门' : (pool.dns_provider_id ? 'DNS 托管' : '未绑定') }}</strong></div></div><div class="pool-row-wide pool-warnings" v-if="pool.front_door_mode==='dispatcher' || (pool.enabled && activeMembers(pool) > 0 && onlineMembers(pool) === 0) || sharedAccountNames(pool).length"><div class="pool-warning" v-if="pool.front_door_mode==='dispatcher'">固定 Dispatcher 模式不会发布 Relay IP；请将此域名指向两台以上独立网关。</div><div class="pool-warning" v-else-if="pool.enabled && activeMembers(pool) > 0 && onlineMembers(pool) === 0">当前没有可接收新连接的 Relay；DNS 不会发布不健康成员。</div><div class="pool-warning" v-if="sharedAccountNames(pool).length">{{ sharedAccountNames(pool).join('、') }} 绑定了多台 Relay，但这些 Relay 共享同一账户额度，不会叠加 200 GB。</div></div><div class="pool-row-members mt-4 space-y-2"><div v-for="member in pool.members" :key="member.id" class="member-line"><span class="status-dot" :class="member.enabled&&member.status==='online'?'status-dot-success':'status-dot-muted'"></span><span class="min-w-0 flex-1 truncate"><strong class="member-name">{{ member.relay_node_name }}</strong><small v-if="member.traffic_known" class="member-traffic">{{ formatTraffic(member.traffic_used_gb, 1) }} / {{ formatTraffic(member.traffic_limit_gb, 0) }} GB · {{ formatTraffic(member.traffic_percent, 1) }}%<template v-if="safeNumber(member.traffic_rate_gb_per_minute) > 0"> · {{ formatTraffic(member.traffic_rate_gb_per_minute, 3) }} GB/分钟</template><template v-if="safeNumber(member.traffic_minutes_to_threshold) > 0"> · 约 {{ Math.ceil(safeNumber(member.traffic_minutes_to_threshold)) }} 分钟到阈值</template></small><small v-else class="member-traffic">账户流量待同步</small></span><span class="font-mono text-[10px] text-slate-400"><MaskedIP :value="member.public_ip" placeholder="未上报 IP" class="member-ip" /></span><span v-if="member.protection_triggered" class="drain-reason">{{ member.protection_predictive ? '预测排空' : '流量保护' }}</span><span class="state-mini" :class="member.enabled&&member.status==='online'?'state-mini-online':''">{{ member.enabled ? (member.status==='online'?'在线':member.status==='draining'?'排空中':'待上线') : '已排空' }}</span></div></div><div class="pool-row-actions mt-4 flex justify-end gap-1 border-t border-slate-100 pt-3"><button class="btn-ghost px-2 py-1 text-xs" @click="openEdit(pool)">编辑</button><button class="btn-danger px-2 py-1 text-xs" @click="remove(pool)">删除入口池</button></div></article><div v-if="!store.pools.length" class="card empty-panel layout-card xl:col-span-2">还没有逻辑入口池</div></section>

    <Modal v-if="showForm" size="large" @close="showForm=false">
      <form class="space-y-5 modal-form" @submit.prevent="save">
        <div>
          <div class="eyebrow">LOGICAL ENTRY</div>
          <h2 class="mt-1 text-lg font-bold text-slate-900">{{ editTarget?'编辑入口池':'创建入口池' }}</h2>
          <p class="modal-form-subtitle">选择 DNS Provider 后只需填写记录名，完整入口域名会自动生成。</p>
        </div>
        <div class="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div class="sm:col-span-2"><label class="field-label">入口池名称</label><input v-model.trim="form.name" class="input" placeholder="例如：主入口" required /></div>
          <div class="sm:col-span-2"><label class="field-label">公网入口模式</label><select v-model="form.front_door_mode" class="input"><option value="relay_dns">DNS 多 A（自动发布健康 Relay IP）</option><option value="dispatcher">固定 Dispatcher（由网关负责公网入口）</option></select><p class="field-hint">DNS 多 A 模式使用下方 Provider；Dispatcher 模式需要填写网关实际使用的完整域名。</p></div>
          <template v-if="form.front_door_mode==='relay_dns'">
            <div><label class="field-label">DNS Provider</label><select v-model="form.dns_provider_id" class="input"><option v-for="provider in store.dnsProviders" :key="provider.id" :value="provider.id">{{ provider.name }} · {{ provider.zone }}</option><option value="">不自动托管（手动填写完整入口域名）</option></select></div>
            <div v-if="selectedDNSProvider" class="derived-field-wrap"><label class="field-label">入口记录名</label><input v-model.trim="form.dns_record_name" class="input" placeholder="例如：sgrelay" /><div class="entry-preview"><span>完整入口域名（自动）</span><code>{{ entryHostnamePreview || '填写记录名后自动生成' }}<template v-if="entryHostnamePreview">:{{ form.listen_port }}</template></code></div><p class="field-hint">记录名是所选 Zone 内的相对名称，例如 sgrelay + {{ selectedDNSProvider.zone }} = sgrelay.{{ selectedDNSProvider.zone }}。</p></div>
            <div v-else class="sm:col-span-2"><label class="field-label">入口域名</label><input v-model.trim="form.hostname" class="input" placeholder="例如：relay.example.com" /><p class="field-hint">未绑定 DNS Provider 时，系统不会自动改 DNS，请填写用户实际使用的完整域名。</p></div>
            <div v-if="selectedDNSProvider"><label class="field-label">DNS TTL</label><select v-model.number="form.dns_ttl" class="input"><option v-for="option in dnsTTLOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><p class="field-hint">{{ dnsTTLHint }}</p></div>
          </template>
          <template v-else>
            <div class="sm:col-span-2"><label class="field-label">固定入口域名</label><input v-model.trim="form.hostname" class="input" placeholder="例如：relay.example.com" required /><p class="field-hint">这是 Dispatcher 网关对外提供服务的完整域名；控制器不会为它托管 DNS。</p></div>
          </template>
          <div><label class="field-label">监听端口</label><input v-model.number="form.listen_port" type="number" min="1" max="65535" class="input" required /></div>
          <div><label class="field-label">转发协议</label><select v-model="form.network" class="input"><option value="tcp">TCP</option><option value="udp">UDP</option><option value="tcp+udp">TCP + UDP</option></select></div>
          <div><label class="field-label">Relay 内部调度</label><select v-model="form.mode" class="input"><option value="failover">主备</option><option value="round_robin">轮询</option><option value="weighted">加权</option><option value="ip_hash">IP Hash</option></select></div>
          <label class="flex items-center gap-2 self-end pb-2 text-sm text-slate-600"><input v-model="form.enabled" type="checkbox" />启用入口池</label>
          <label class="flex items-center gap-2 self-end pb-2 text-sm text-slate-600"><input v-model="form.auto_drain" type="checkbox" />流量达阈值自动排空</label>
          <p class="field-wide field-hint">自动排空读取账户级 CDT 快照，并根据最近增速预留控制与 DNS 生效窗口；预计到达阈值时会提前撤下入口并停止新连接。</p>
        </div>
        <div class="modal-resource-grid">
          <div><label class="field-label">绑定 CDT Relay</label><div class="target-picker"><label v-for="(node,index) in store.relayNodes" :key="node.id" class="target-option"><input v-model="selectedMembers" type="checkbox" :value="node.id" /><span class="min-w-0 flex-1"><strong>{{ node.name }}</strong><small><MaskedIP :value="node.public_ip" placeholder="未上报 IP" /> · {{ node.status }}</small></span><input v-if="selectedMembers.includes(node.id)" v-model.number="memberOptions[node.id].weight" type="number" min="1" class="mini-input" title="Relay 权重" /></label></div><p class="field-hint">成员权重只影响单台 Relay 选择落地目标；普通多 A DNS 不会按该权重分配入口流量。要叠加 CDT 额度，请优先使用独立计费账户。</p></div>
          <div><label class="field-label">落地目标</label><div class="target-picker"><label v-for="(node,index) in store.landingNodes" :key="node.id" class="target-option"><input v-model="selectedTargets" type="checkbox" :value="node.id" /><span class="min-w-0 flex-1"><strong>{{ node.name }}</strong><small><MaskedIP :value="node.address" :suffix="`:${node.port}`" placeholder="未设置地址" /></small></span><input v-if="selectedTargets.includes(node.id)" v-model.number="targetOptions[node.id].priority" type="number" class="mini-input" title="优先级" /><input v-if="selectedTargets.includes(node.id)" v-model.number="targetOptions[node.id].weight" type="number" class="mini-input" title="落地权重" /></label></div><p class="field-hint">多个目标仅适用于共享同一协议和凭证的副本；不同 SS/VLESS 节点请使用不同端口的入口池。</p></div>
        </div>
        <div v-if="formError" class="notice notice-error">{{ formError }}</div>
        <div class="modal-form-actions"><button type="button" class="btn-ghost" @click="showForm=false">取消</button><button class="btn-primary" :disabled="saving">{{ saving?'发布中...':'保存并发布' }}</button></div>
      </form>
    </Modal>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRelayStore } from '../stores/relay'
import Modal from '../components/Modal.vue'
import MaskedIP from '../components/MaskedIP.vue'
import { normalizeTTLForProvider, ttlHint, ttlOptions } from '../utils/dns'
const store=useRelayStore();const showForm=ref(false);const editTarget=ref(null);const saving=ref(false);const formError=ref('');const message=ref('');const messageType=ref('success');const selectedMembers=ref([]);const selectedTargets=ref([]);const memberOptions=reactive({});const targetOptions=reactive({})
const blank=()=>({name:'',hostname:'',front_door_mode:'relay_dns',listen_port:443,network:'tcp',mode:'failover',enabled:true,auto_drain:true,dns_provider_id:'',dns_record_name:'',dns_ttl:60});const form=ref(blank());const selectedDNSProvider=computed(()=>store.dnsProviders.find(provider=>String(provider.id)===String(form.value.dns_provider_id)));const dnsTTLOptions=computed(()=>ttlOptions(selectedDNSProvider.value,form.value.dns_ttl));const dnsTTLHint=computed(()=>ttlHint(selectedDNSProvider.value));const entryHostnamePreview=computed(()=>form.value.front_door_mode==='relay_dns'&&selectedDNSProvider.value?composeEntryHostname(form.value.dns_record_name,selectedDNSProvider.value.zone):String(form.value.hostname||'').trim());const canCreate=computed(()=>store.relayNodes.length>0&&store.landingNodes.length>0)
function normalizeDNSRecordName(value,zone){const host=String(value||'').trim().replace(/\.$/,'');const root=String(zone||'').trim().replace(/\.$/,'');if(!host)return '';if(host==='@'||(root&&host.toLowerCase()===root.toLowerCase()))return '@';const suffix='.'+root;return root&&host.toLowerCase().endsWith(suffix.toLowerCase())?host.slice(0,-suffix.length):host}
function deriveDNSRecordName(hostname,zone){return normalizeDNSRecordName(hostname,zone)}
function composeEntryHostname(recordName,zone){const record=normalizeDNSRecordName(recordName,zone);const root=String(zone||'').trim().replace(/\.$/,'');if(!record)return '';if(record==='@'||!root)return record==='@'?root:record;return record.toLowerCase().endsWith('.'+root.toLowerCase())?record:record+'.'+root}
watch(()=>form.value.dns_provider_id,(next,previous)=>{const previousProvider=store.dnsProviders.find(provider=>String(provider.id)===String(previous));if(!next&&previousProvider&&form.value.dns_record_name){form.value.hostname=composeEntryHostname(form.value.dns_record_name,previousProvider.zone);form.value.dns_ttl=normalizeTTLForProvider(form.value.dns_ttl,null);return}const provider=store.dnsProviders.find(item=>String(item.id)===String(next));if(next&&provider){form.value.dns_ttl=normalizeTTLForProvider(form.value.dns_ttl,provider);if(!form.value.dns_record_name&&form.value.hostname){form.value.dns_record_name=deriveDNSRecordName(form.value.hostname,provider.zone)}}})
function ensureOptions(){store.relayNodes.forEach((node,index)=>{if(!memberOptions[node.id])memberOptions[node.id]={weight:1}});store.landingNodes.forEach((node,index)=>{if(!targetOptions[node.id])targetOptions[node.id]={priority:index*10,weight:1}})}
function openCreate(){ensureOptions();editTarget.value=null;const next=blank();next.dns_provider_id=store.dnsProviders[0]?.id||'';form.value=next;selectedMembers.value=[];selectedTargets.value=[];formError.value='';showForm.value=true}
function openEdit(pool){ensureOptions();editTarget.value=pool;const provider=store.dnsProviders.find(item=>String(item.id)===String(pool.dns_provider_id));form.value={name:pool.name,hostname:pool.hostname,front_door_mode:pool.front_door_mode||'relay_dns',listen_port:pool.listen_port,network:pool.network,mode:pool.mode,enabled:pool.enabled,auto_drain:pool.auto_drain !== false,dns_provider_id:pool.dns_provider_id||'',dns_record_name:pool.dns_record_name||deriveDNSRecordName(pool.hostname,provider?.zone||''),dns_ttl:normalizeTTLForProvider(pool.dns_ttl||60,provider)};selectedMembers.value=pool.members.filter(m=>m.enabled).map(m=>m.relay_node_id);pool.members.forEach(m=>{memberOptions[m.relay_node_id]={weight:m.weight||1}});selectedTargets.value=pool.targets.map(t=>t.landing_node_id);pool.targets.forEach(t=>{targetOptions[t.landing_node_id]={priority:t.priority,weight:t.weight}});formError.value='';showForm.value=true}
async function save(){if(!selectedMembers.value.length){formError.value='至少选择一台 CDT Relay';return}if(!selectedTargets.value.length){formError.value='至少选择一个落地目标';return}const mode=form.value.front_door_mode;const provider=selectedDNSProvider.value;let hostname=String(form.value.hostname||'').trim();let dnsRecordName='';if(mode==='relay_dns'&&provider){dnsRecordName=normalizeDNSRecordName(form.value.dns_record_name,provider.zone);if(!dnsRecordName){formError.value='请填写入口记录名';return}hostname=composeEntryHostname(dnsRecordName,provider.zone)}if(!hostname){formError.value=mode==='dispatcher'?'请填写固定入口域名':'请填写入口域名';return}saving.value=true;formError.value='';const payload={...form.value,hostname,dns_provider_id:mode==='dispatcher'?'':form.value.dns_provider_id,dns_record_name:dnsRecordName,dns_ttl:provider?normalizeTTLForProvider(form.value.dns_ttl,provider):60,members:selectedMembers.value.map(id=>({relay_node_id:id,weight:Number(memberOptions[id]?.weight||1),enabled:true})),targets:selectedTargets.value.map(id=>({landing_node_id:id,priority:Number(targetOptions[id]?.priority||0),weight:Number(targetOptions[id]?.weight||1),enabled:true})),dial_timeout_ms:2500,udp_idle_timeout_seconds:60,health:{enabled:true,interval_seconds:4,timeout_ms:2000,failure_threshold:2,success_threshold:3,recovery_cooldown_seconds:60}};try{if(editTarget.value)await store.updatePool(editTarget.value.id,payload);else await store.createPool(payload);showForm.value=false;showMessage('入口池已发布，Relay 将自动热更新')}catch(e){formError.value=e.response?.data?.error||'发布失败'}finally{saving.value=false}}
async function remove(pool){if(!window.confirm(`确认永久删除入口池“${pool.name}”？关联的 Relay 服务和 DNS 记录会一并删除。`))return;try{await store.deletePool(pool.id);showMessage('入口池及关联 DNS 已删除')}catch(e){showMessage(e.response?.data?.error||'删除失败','error')}}
function safeNumber(value, fallback=0){const number=Number(value);return Number.isFinite(number)?number:fallback}function formatTraffic(value,digits){return safeNumber(value).toFixed(digits)}function activeMembers(pool){return pool.members.filter(m=>m.enabled).length}function onlineMembers(pool){return pool.members.filter(m=>m.enabled&&m.status==='online').length}function sharedAccountNames(pool){const counts={};pool.members.filter(m=>m.enabled&&m.cloud_account_id).forEach(m=>{const key=String(m.cloud_account_id);if(!counts[key])counts[key]={name:m.cloud_account_name||`账户 ${key}`,count:0};counts[key].count++});return Object.values(counts).filter(item=>item.count>1).map(item=>item.name)}function showMessage(text,type='success'){message.value=text;messageType.value=type;setTimeout(()=>message.value='',5000)}onMounted(async()=>{await store.fetchAll();ensureOptions()})
</script>

<style scoped>
.eyebrow{color:#2563eb;font-size:10px;font-weight:800;letter-spacing:.16em}.page-title{margin-top:5px;color:#172033;font-size:27px;font-weight:750;letter-spacing:-.03em}.page-subtitle{margin-top:5px;color:#64748b;font-size:12px}.pool-mark{display:inline-flex;align-items:center;justify-content:center;border-radius:7px;background:#eef2ff;padding:6px 7px;color:#4f46e5;font-size:9px;font-weight:800;letter-spacing:.04em}.pool-badges{display:flex;flex:0 0 auto;flex-wrap:wrap;justify-content:flex-end;gap:5px}.auto-drain-tag{border-radius:999px;background:#eff6ff;padding:5px 9px;color:#1d4ed8;font-size:9px;font-weight:750}.state-tag{border-radius:999px;background:#f1f5f9;padding:5px 9px;color:#64748b;font-size:10px;font-weight:700}.state-online{background:#ecfdf3;color:#15803d}.info-box{min-width:0;border-radius:8px;background:#f8fafc;padding:9px}.info-box span{display:block;color:#94a3b8;font-size:9px}.info-box strong{display:block;overflow:hidden;margin-top:4px;color:#475569;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.pool-warning{margin-top:12px;border:1px solid #fed7aa;border-radius:8px;background:#fff7ed;padding:8px 10px;color:#9a3412;font-size:10px;line-height:1.5}.member-line{display:flex;align-items:center;gap:8px;border-radius:7px;background:#f8fafc;padding:8px 9px;color:#64748b;font-size:10px}.member-name{display:block;color:#64748b;font-size:10px;font-weight:600}.member-traffic{display:block;margin-top:2px;color:#94a3b8;font-size:9px}.drain-reason{border-radius:999px;background:#fef3c7;padding:3px 6px;color:#a16207;font-size:9px;font-weight:700}.state-mini{border-radius:999px;background:#f1f5f9;padding:3px 6px;color:#94a3b8;font-size:9px;font-weight:700}.state-mini-online{background:#ecfdf3;color:#15803d}.target-picker{max-height:260px;overflow:auto;border:1px solid #e5eaf1;border-radius:9px}.target-option{display:flex;align-items:center;gap:9px;padding:10px 12px;border-bottom:1px solid #f1f5f9}.target-option:last-child{border:0}.target-option strong,.target-option small{display:block}.target-option strong{color:#475569;font-size:11px}.target-option small{margin-top:2px;color:#94a3b8;font-size:9px}.mini-input{width:52px;min-width:0;border:1px solid #d8e0eb;border-radius:6px;padding:5px;color:#475569;font-size:10px}.empty-panel{padding:52px;text-align:center;color:#94a3b8;font-size:12px}@media(max-width:480px){.member-line{flex-wrap:wrap}.target-option{flex-wrap:wrap}.target-option span{min-width:0;flex:1 1 100%}}
.derived-field-wrap{min-width:0}.derived-field{display:flex;min-height:41px;align-items:center;justify-content:space-between;gap:8px;border:1px solid #d8e0eb;border-radius:9px;background:#f8fafc;padding:0 12px;color:#475569;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}.derived-field-disabled{color:#94a3b8;background:#f1f5f9}.derived-badge{border-radius:999px;background:#dbeafe;padding:3px 7px;color:#1d4ed8;font-family:inherit;font-size:9px;font-weight:700}
.entry-preview{display:grid;gap:4px;margin-top:8px;border:1px solid #dbeafe;border-radius:9px;background:#f8fbff;padding:9px 11px}.entry-preview span{color:#64748b;font-size:9px}.entry-preview code{color:#1e3a8a;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;overflow-wrap:anywhere}
</style>
